// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * The zones as a table (the table layout of ZoneTable): the zone and its areas, the price, free from, the
 * minimum order, the time and an express badge.
 */
import { For, type JSX } from "solid-js";
import { Badge, Box, Stack, Table, TableBody, TableCaption, TableCell, TableHead, TableHeadCell, TableRow, Text } from "../compose";
import { fmtMoney } from "../utils";
import type { Zone, ZoneLabels } from "../blocks/zone-table.types";

export type ZoneRowsProps = {
  zones: Zone[];
  labels: ZoneLabels;
};

export function ZoneRows({ zones, labels }: ZoneRowsProps) {
  return (
    <Box class="w-full overflow-x-auto rounded inset-ring inset-ring-border">
      <Table class="w-full text-left text-sm" data-testid="zone-table">
        <TableCaption class="sr-only">
          {labels.caption}
        </TableCaption>
        <TableHead class="bg-muted">
          <TableRow>
            <TableHeadCell scope="col" class="px-4 py-2">
              {labels.zone}
            </TableHeadCell>
            <TableHeadCell scope="col" class="py-2">
              {labels.price}
            </TableHeadCell>
            <TableHeadCell scope="col" class="py-2">
              {labels.freeFrom}
            </TableHeadCell>
            <TableHeadCell scope="col" class="hidden py-2 md:table-cell">
              {labels.minOrder}
            </TableHeadCell>
            <TableHeadCell scope="col" class="py-2">
              {labels.time}
            </TableHeadCell>
            <TableHeadCell scope="col" class="hidden py-2 pr-4 sm:table-cell">
              {labels.express}
            </TableHeadCell>
          </TableRow>
        </TableHead>
        <TableBody>
          <For each={zones ?? []}>{(z) => (
            <TableRow class="border-t border-border" data-testid="item">
              <TableCell class="px-4 py-4">
                <Stack gap="0">
                  <Text size="sm" weight="semibold">
                    {z.name}
                  </Text>
                  <Text size="xs" class="text-muted-foreground">
                    {z.area}
                  </Text>
                </Stack>
              </TableCell>
              <TableCell class="font-medium">
                {fmtMoney(z.price, z.currency)}
              </TableCell>
              <TableCell>
                {fmtMoney(z.freeFrom, z.currency)}
              </TableCell>
              <TableCell class="hidden md:table-cell">
                {fmtMoney(z.minOrder, z.currency)}
              </TableCell>
              <TableCell>
                {z.time}
              </TableCell>
              <TableCell class="hidden pr-4 sm:table-cell">
                {z.express ? (
                  <Badge variant="secondary" size="default">
                    {z.express}
                  </Badge>
                ) : null}
              </TableCell>
            </TableRow>
          )}</For>
        </TableBody>
      </Table>
    </Box>
  );
}
